#include <stdlib.h>
#include <assert.h>

typedef struct TreeNode {
    int value;
    struct TreeNode* left;
    struct TreeNode* right;
    struct TreeNode* parent;
} TreeNode;

TreeNode* create_node(int value) {
    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));
    assert(node != NULL);

    node->value = value;
    node->left = NULL;
    node->right = NULL;
    node->parent = NULL;

    return node;
}

int find_min_index(int* sequence, int length) {
    assert(sequence != NULL);
    assert(length > 0);

    int min_idx = 0;
    for (int i = 1; i < length; i++) {
        if (sequence[i] < sequence[min_idx]) {
            min_idx = i;
        }
    }
    return min_idx;
}

TreeNode* construct_cartesian_tree(int* sequence, int length) {
    assert(sequence != NULL);
    assert(length >= 0);

    if (length == 0) {
        return NULL;
    }

    if (length == 1) {
        return create_node(sequence[0]);
    }

    // Find minimum element index
    int min_idx = find_min_index(sequence, length);
    TreeNode* root = create_node(sequence[min_idx]);

    // Construct left subtree
    if (min_idx > 0) {
        root->left = construct_cartesian_tree(sequence, min_idx);
        if (root->left != NULL) {
            root->left->parent = root;
        }
    }

    // Construct right subtree
    if (min_idx < length - 1) {
        root->right = construct_cartesian_tree(sequence + min_idx + 1, length - min_idx - 1);
        if (root->right != NULL) {
            root->right->parent = root;
        }
    }

    return root;
}

void verify_distinct_values(int* sequence, int length) {
    for (int i = 0; i < length; i++) {
        for (int j = i + 1; j < length; j++) {
            assert(sequence[i] != sequence[j]);
        }
    }
}

